<script lang="ts">import gsap from 'gsap';import { Check,Keyboard } from 'lucide-svelte';let { word,acceptedAnswers,oncounts }=$props<{word:string;acceptedAnswers:string[];oncounts:(correct:number,errors:number)=>void}>();let value=$state(''),correct=$state(0),errors=$state(0),invalid=$state(false),input:HTMLInputElement;const normalize=(v:string)=>v.normalize('NFKC').trim().toLocaleLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ');function submit(){const options=[word,...acceptedAnswers].map(normalize);if(options.includes(normalize(value))){correct++;value='';invalid=false;oncounts(correct,errors);requestAnimationFrame(()=>input.focus())}else{errors++;invalid=true;oncounts(correct,errors);gsap.fromTo(input,{x:-3},{x:0,duration:.16,ease:'elastic.out(1,.25)',clearProps:'transform'});input.focus()}}</script>
<section class:invalid><div class="label"><Keyboard size={15}/><span>Typing practice</span><small>{correct} correct</small></div><form onsubmit={(e)=>{e.preventDefault();submit()}}><input bind:this={input} bind:value oninput={()=>invalid=false} autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type the word, then press Enter" aria-invalid={invalid}/><button aria-label="Check spelling"><Check size={17}/></button></form>{#if invalid}<p>Not quite — keep the text and try again.</p>{/if}</section>
<style>section{padding:14px;background:var(--surface-2);border:1px solid var(--border);border-radius:11px}.label{display:flex;align-items:center;gap:7px;margin-bottom:9px;color:var(--text-secondary);font-size:12px}.label small{margin-left:auto;color:var(--success)}form{display:flex;gap:8px}input{height:40px}form button{width:42px;border-radius:9px;border:1px solid var(--border);background:var(--surface-1);color:var(--text-secondary)}section.invalid{border-color:#d8485b66;box-shadow:0 0 0 2px var(--danger-soft)}p{margin-top:7px;color:#b33143;font-size:11px}</style>
